#include <bits/stdc++.h>
using namespace std;

struct Components {
    vector<int> label;
    vector<int> reps;
};

Components find_components(const vector<vector<int>>& adj) {
    int cnt = static_cast<int>(adj.size()) - 1;
    Components result{vector<int>(cnt + 1), {}};
    queue<int> pending;

for (int start = 1; start <= cnt; ++start) {
    if (result.label[start] != 0) {
        continue;
    }
    result.reps.push_back(start);
    int component = static_cast<int>(result.reps.size());
    result.label[start] = component;
    pending.push(start);
    while (!pending.empty()) {
        int vertex = pending.front();
        pending.pop();
        for (int next : adj[vertex]) {
            if (result.label[next] == 0) {
                result.label[next] = component;
                pending.push(next);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    for (int edge = 0; edge < m; ++edge) {
        int first, second;
        cin >> first >> second;
        adj[first].push_back(second);
        adj[second].push_back(first);
    }
    Components result = find_components(adj);
    cout << result.reps.size() - 1 << '\n';
    for (int i = 1; i < static_cast<int>(result.reps.size()); ++i) {
        cout << result.reps[0] << ' ' << result.reps[i] << '\n';
    }
}

